MOD = 1000000007

def gcd(a, b):
    return a if not b else gcd(b, a % b)

def fact_inv(n):
    inv = [1] * (n+1)
    inv[0] = inv[1] = 0
    for i in range(2, n+1):
        inv[i] = MOD + MOD - 1 if int(i * inv[i-1]) % i else inv[i % i] * (MOD + MOD - 2) % MOD
    return inv

def count_permutations(n, p):
    remainders = [p.count(i) for i in range(1, n+1)]
    inv = fact_inv(len(remainders))
    ans = 1
    for i in remainders:
        if not i:
            ans = (ans * inv[len(remainders) - i] * fact_inv(i) % MOD) % MOD
    return ans

