def is_point_inside_polygon(polygon, x, y):
    n = len(polygon)
    inside = False
    xi, yi = x, y
    for i in range(n + 1):
        xi, yi = polygon[i % n][0], polygon[i % n][1]
        if yi > yi:
            if y <= yi or (y > yi and xi <= xi):
                inside = not inside
        else:
            if y <= yi or (y > yi and xi >= xi):
                inside = not inside

    return inside

def count_properties_in_circle(area_center, area_radius, x, y, outer_radius):
    total_area = 0
    count = 0
    for i in range(outer_radius, area_radius + 1):
        intersects_count = 0
        p0_x, p0_y = area_center
        for j in range(i, area_radius + 1):
            p1_x, p1_y = (p0_x + i + (j - area_radius) % i, p0_y)
            if p1_x == p0_x and p1_y == p0_y:
                p1_x += 1
            p2_x, p2_y = (p0_x + j, p0_y)
            if p2_x == p0_x and p2_y == p0_y:
                p2_y += 1

            p0_x, p0_y = p1_x, p1_y
            cpx = p0_x - x
            cpy = p0_y - y
            d = (cpx ** 2 + cpy ** 2) ** 0.5
            if d > outer_radius:
                continue
            if cpx == 0:
                atan = 90 if cpy < 0 else -90
            elif cpy == 0:
                atan = 0 if cpx > 0 else 180
            else:
                atan = math.degrees(math.atan(cpy / cpx)) if cpx > 0 else (math.degrees(math.atan(cpy / cpx)) + 180)
            if atan > 180:
                atan -= 180
            if not (-180 <= atan <= 180) or cpx * d < d * d * math.tan(math.radians(-90 + atan))**2:
                intersections = calculate_distance(x, y, area_center, i)
                intersects_count += 1
            p0_x, p0_y = p2_x, p2_y
        total_area += min(intersects_count, i - outer_radius)

