import sys
from collections import deque

def is_possible_path(path1, path2):
    """Check if two paths can be concatenated at their ends"""
    if (len(path1) % 2) or (len(path2) % 2):
        return False

    # Stack to temporarily store matching elements from both paths
    stack = deque()

    idx1 = 0
    idx2 = 0
    while idx1 < len(path1) and idx2 < len(path2):
        if path1[idx1] == path2[idx2]:
            stack.append((path1[idx1], idx1 + 1, idx2 + 1))
            idx1 += 1
            idx2 += 1
        elif path1[idx1] == 'N' and path2[idx2] == 'S':
            # Move upwards if nodes in both paths are N on either side
            while idx1 < len(path1) and path1[idx1] == 'N':
                stack.append((path1[idx1], idx1 + 1, idx2))
                idx1 += 1
            while idx2 < len(path2) and (path2[idx2] == 'N' or path2[idx2] == 'S'):
                stack.append((path2[idx2], idx2 + 1, idx2 + 1))
                idx2 += 1
        elif path1[idx1] == 'E' and path2[idx2] == 'W':
            # Move horizontally if nodes in both paths are E on either side
            while idx1 < len(path1) and path1[idx1] == 'E':
                stack.append((path1[idx1], idx1 + 1, idx2))
                idx1 += 1
            while idx2 < len(path2) and (path2[idx2] == 'E' or path2[idx2] == 'W'):
                stack.append((path2[idx2], idx2 + 1, idx2 + 1))
                idx2 += 1
        elif path1[idx1] == 'W' and path2[idx2] == 'E':
            # Move horizontally if nodes in both paths are W on either side
            while idx1 < len(path1) and path1[idx1] == 'W':
                stack.append((path1[idx1], idx1 + 1, idx2))
                idx1 += 1
            while idx2 < len(path2) and (path2[idx2] == 'W' or path2[idx2] == 'E'):
                stack.append((path2[idx2], idx2 + 1, idx2 + 1))
                idx2 += 1

    # Check if all elements have been matched
    return not (len(path1) % 2 or len(path2) % 2 or len(stack) != 0)

