    mod = 10**8 + 7
    sequences = []

    for seq in itertools.product(range(2), repeat=2):
        prob = []
        for W, B in zip(C_W, C_B):
            prob.append(seq[0] * B + seq[1] * W)
        sequences.append(prob)

    cost_values = []
    for i, sequence in enumerate(sequences):
        total_cost = 0
        for prob in sequence:
            temp_cost = (prob[0] * prob[0] + prob[1] * prob[1]) % mod
            total_cost += temp_cost
            total_cost %= mod
