def find_components(edges, n):
    # Initialize a set to keep track of connected components
    connected_components = set()

    def bfs(s):
        queue = [s]
        visited = {s}

        while queue:
            node = queue.pop(0)
            for neighbor in range(2**n):
                if neighbor not in visited and node & neighbor == node:
                    visited.add(neighbor)
                    queue.append(neighbor)

        connected_components.add(tuple(e for e in edges if edge.e[v] == node))

    components = 0
    for node in range(2**n):
        if node not in visited:
            components += 1
            bfs(node)

    return components

