from collections import Counter

def calculate_winner_positions(black_tokens):
    black_positions = dict(black_tokens)
    point_votes = Counter((x - y) % 2 for y in black_positions.values() for x in black_positions)
    directions = sum(2 * p for p in point_votes.values())
    black_token_count = len(black_positions)
    half_moves = (black_token_count * (black_token_count - 1)) // 2
    if directions == 0:
        return 0
    elif directions == 1:
        return half_moves - 2 * (black_token_count - 1)
    elif directions == 2:
        return half_moves
    else:
        return half_moves + 2 * (black_token_count - 1)

