def ways(n, fixeds):
    if len(fixeds) == n:
        return 1
    # Use the last number or not
    use_last = ways(n, fixeds[1:]) if fixeds[0] == 1 else 0
    # Disregard it, in which case the remaining (n - 1) numbers can be any
    dont_use_last = (n - 1) * ways(n - 1, fixeds[:-1]) % MOD
    return (use_last + dont_use_last) % MOD

