from collections import defaultdict

def solve(n, m, ropes, q, queries):
    # Dictionary to store the maximum reachable heights from each position on the trunk
    reachable = defaultdict(lambda: -1)
    for r in reversed(ropes):
        for i in range((1 << m), 0, -1):
            prev_height = k = n // 2
            while i & k:
                if reachable[k-m+1] != -1:
                    break
                k -= 1
            if k != 0:
                prev_height = max(reachable[k-m+1], prev_height)
        get_height = n
        for i in range(m-1, -1, -1):
            h = get_height
            if i < k:
                if h == ropes[i][0]:
                    get_height = min(h, ropes[i+k-i][0])
                else:
                    get_height = max(h, ropes[i+k-i][1])
                reach = reachable.get(k, "max")
                if reach == -1 or reach > get_height:
                    reachable[k] = get_height
                prev_height = min(prev_height, get_height)

    results = []
    for x, y in queries:
        reachable[0] = x - 1
        height = x
        while reachable[-1] < y:
            if height >= reachable[-1]:
                break
            reachable[0], reachable[-1] = reachable[-1], height
            for end in range(1, m):
                lower = max(x, reachable[end-1])
                upper = min(y, reachable[-1])
                if lower <= height < upper:
                    reachable[end] = max(height, reachable[end-1], reachable[-1])
                height = upper
        results.append(str(reachable[0]))
    return results

