def calculate_intersection(x1, y1, x2, y2):
    denominator = (x1 - x2) * (y3 - y1) - (y1 - y2) * (x3 - x1)
    if denominator == 0:
        return None
    x = ((x1 * y2 - y1 * x2) * (x3 - x1) - (y1 - y2) * (x2 * x3 - x1 * x3)) / denominator
    y = ((x1 * y2 - y1 * x2) * (y3 - y1) - (y1 - y2) * (y2 * y3 - y1 * y3)) / denominator
    assert math.isclose(x1, x, abs_tol=1e-9)
