        self.graph = defaultdict(list)

    def add_edge(self, u, v):
        self.graph[u].append(v)
        self.graph[v].append(u)

    def is_cyclic(self, mask, u):
        stack = [u]
        visited = [False] * (1 << self.n)
        visited[mask] = True
        while stack:
            node = stack.pop()
            for child in self.graph[node]:
                if visited[1 << child] != mask:
                    checked = int(not mask & (1 << child))
                    for mask_1, mask_2 in ((checked, int(not mask_1)), (int(not checked), mask_2)):
                        if self.is_cyclic((1 << node) | mask_1, child):
                            return True

