        s = math.sqrt(min(r1, r2) * max(r1, r2) - (distance**2 - (r1 - r2)**2))
        angle = 2 * math.asin(s / (2 * r1))
        return math.pi * (r1**2 - s**2 / 2)

def area_intersection(poly1, poly2, r):
    total_area = 0.0
    for i in range(len(poly2)):
        for j in range(i+1, len(poly2)):
            p1, p2 = poly2[i], poly2[j]
            area = 0.5 * (max(p1[0], p2[0]) - min(p1[0], p2[0])) * (max(p1[1], p2[1]) - min(p1[1], p2[1]))
            for p3 in poly1:
                if 0 < circle_intersection(p1, r, p3, r) < 2 * r:
                    area += circle_intersection(p1, r, p3, r)
                if 0 < circle_intersection(p2, r, p3, r) < 2 * r:
                    area += circle_intersection(p2, r, p3, r)
    return total_area

def main():
