def calculate_cost(board, C_W, C_B):
    cost = 0
    black_reachable = [[False] * len(board[0]) for _ in range(len(board))]
    white_reachable = [[False] * len(board[0]) for _ in range(len(board))]

    horizontal_reach = 1
    while horizontal_reach < len(board):
        for i in range(len(board) - horizontal_reach):
            has_black = False
            for j in range(horizontal_reach):
                if board[i+j][i] == '0':
                    has_black = True
                    white_reachable[i][j+i] = True
                    break
            if not has_black:
                white_reachable[i][0] = True
                break
        horizontal_reach += 1

    vertical_reach = 1
    while vertical_reach < len(board[0]):
        for j in range(len(board[0]) - vertical_reach):
            has_white = False
            for i in range(len(board)):
                if board[i][j+vertical_reach-1] == '1':
                    has_white = True
                    black_reachable[i][j] = True
                    break
            if not has_white:
                black_reachable[i][0] = True
                break
        vertical_reach += 1

    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == '?' and not black_reachable[i][j] and not white_reachable[i][j]:
                for k in range(C_W, min(C_B, len(board))):
                    if white_reachable[i][j+k] and black_reachable[i+k][j]:
                        if k <= C_B:
                            cost += C_B * (len(board[i+k]) - 1)
                        cost += k - C_B * (max(C_W, k-1)) * (min(C_W, k) - C_B * (len(board[i+k]) - 2))

    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] != "?":
                if not black_reachable[i][j]:
                    if k <= C_B and board[i][j] == '0':
                        cost -= C_B
                    elif k <= C_W and board[i][j] == '1':
                        cost -= k - C_W * (len(board) - 1)

    return cost

