class WaterLevel:
    def getPen(self, inkVal):
        if inkVal <= 1:
            return 1
        divFactors = [i for i in range(2, int(math.sqrt(inkVal)) + 1) if inkVal % i == 0]
        for factor in divFactors[::-1]:
            divs = 0
            while inkVal % factor == 0:
                inkVal = inkVal // factor
                divs += 1
            if divs % 2 == 1:
                return 1
        return 2 if inkVal % 2 == 0 else 1

