    """
    primes = set()
    for i in perm:
        if i > 0:
            primes.add(i)
    primes.sort()
    memo = {}

    def helper(part_perm, current_product, current_lcm):
        if (part_perm, current_product) in memo:
            return memo[(part_perm, current_product)]

        if not part_perm:
            return 1

        next_perm = part_perm.pop()
        total = 1
        for prime in primes:
            if prime < next_perm:
                result = helper(part_perm, next_perm, lcm(first_prime, next_perm))
                total += result
                total %= MOD
            elif prime != next_perm:
                first_prime = lambda: next_prime
                lcm = prime
            else:
                first_prime = lambda: prime
                lcm = current_lcm * prime
        total %= MOD
        memo[(part_perm, current_product)] = total
        return total

    return helper(perm, 1, 1)

