def dfs(node, visited):
    visited.add(node)
    for neighbor in graph[node]:
        if neighbor not in visited:
            dfs(neighbor, visited)

def connected_components_count(n, m, elements):
    k = 2 ** n
    graph = [[] for _ in range(k)]

    for i in range(m):
        x = elements[i]
        for j in range(k):
            if bin(j).count('1') % 2 == bin(x).count('1') % 2:
                graph[j].append(j ^ x)

    count = 0
    visited = set()

    while count < m:
        root = elements[count]
        if root not in visited:
            dfs(root, visited)
            count += 1

    return len(visited)

n, m = map(int, input().split())
